/// <summary>
///     The <c>AVASalesTableFrm_SalesTableDS_AVAItemSet_Extension</c> class is the extension for <c>SalesTable</c>
/// </summary>
[ExtensionOf(formDataSourceStr(SalesTable, SalesTable))]
final class AVASalesTableFrm_SalesTableDS_Extension
{
}

Method.Source:
 /// <summary>
///    AVA <c>active</c> method.
/// </summary>
/// <returns>
///    <c>int</c> as return value
/// </returns>
public int active()
{
    int             retVal;

    SalesTable      locSalesTable;

    retVal = next active();

    locSalesTable               = element.SalesTable_DS.cursor();

    if(locSalesTable.InterCompanyOrder == NoYes::Yes || locSalesTable.InterCompanyDirectDelivery)
    {
        element.avaInterCompanyFields();
    }

    return retVal;
}

/// <summary>
///    AVA <c>write</c> method.
/// </summary>
public void write()
{
    SalesTable      locSalesTable;

    locSalesTable = element.SalesTable_DS.cursor();

    if(     locSalesTable.orig().SalesType  == SalesType::Journal
        &&  locSalesTable.SalesType         == SalesType::Sales
        &&  locSalesTable.AVADlvResponsible == 0                    )
    {
        locSalesTable.AVADlvResponsible = element.avaSetAVADlvResponsible();
        if(locSalesTable.AVADlvResponsible == 0)
        {
            locSalesTable.SalesType = SalesType::Journal;
        }
    }

    next write();

    //element.avaSetAVADlvResponsible(true);
}

/// <summary>
///    AVA <c>validateWrite</c> method.
/// </summary>
/// <returns>
///    <c>int</c> as return value
/// </returns>
boolean validateWrite()
{
    boolean retVal;

    retVal = next validateWrite();

    return retVal;
}
